import{_ as t,c as s,o as a,a3 as o}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Employees","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/index.md","filePath":"master/human-resources/employees/index.md","lastUpdated":1791902625000}'),r={name:"master/human-resources/employees/index.md"};function n(i,e,l,d,p,h){return a(),s("div",null,e[0]||(e[0]=[o(`<h1 id="employees" tabindex="-1">Employees <a class="header-anchor" href="#employees" aria-label="Permalink to &quot;Employees&quot;">​</a></h1><p>The Employees app is the people directory of your company. It holds one profile for every person who works for you: name, job, department, manager, contact details, skills and work history. Other apps read these profiles. Time Off asks who a person&#39;s approver is. Recruitment turns a hired applicant into an employee.</p><blockquote><p><strong>In simple words:</strong> Employees is the single place where you keep who works for you, where they sit in the company and what they can do.</p></blockquote><p>Open the <strong>Employees</strong> app from the main menu. The top menu shows <strong>Employees</strong>, <strong>Departments</strong>, <strong>Reportings</strong> and <strong>Configurations</strong>.</p><h2 id="how-an-employee-moves-through-aureus" tabindex="-1">How an employee moves through Aureus <a class="header-anchor" href="#how-an-employee-moves-through-aureus" aria-label="Permalink to &quot;How an employee moves through Aureus&quot;">​</a></h2><p>Follow these steps in order the first time.</p><ol><li>Set up the places people belong to: departments and job positions.</li><li>Add the employee with the basic profile.</li><li>Build the profile with work details, private details, skills and resumé lines.</li><li>Keep the list tidy with search, tabs, filters and groups.</li><li>Record the departure when the person leaves.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Departments      Job positions</span></span>
<span class="line"><span>      \\              /</span></span>
<span class="line"><span>       v            v</span></span>
<span class="line"><span>     Add employee  ──►  Skills + Resumé  ──►  Employee list  ──►  Departure</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Start here</p><p>The <a href="./get-started/first-steps.html">first steps tutorial</a> walks through all five steps with one example employee, <strong>Priya Sharma</strong>.</p></div><h2 id="the-four-menus" tabindex="-1">The four menus <a class="header-anchor" href="#the-four-menus" aria-label="Permalink to &quot;The four menus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Employees</strong></td><td>The list of people as cards. Open a card to see or edit the profile.</td></tr><tr><td><strong>Departments</strong></td><td>Your company structure, shown as cards. A department can have a parent, a manager and its own list of employees.</td></tr><tr><td><strong>Reportings</strong></td><td>A read-only report of skills per employee.</td></tr><tr><td><strong>Configurations</strong></td><td>The lists that feed the forms: <strong>Activity Plans</strong>, <strong>Departure Reasons</strong>, <strong>Tags</strong>, <strong>Work Locations</strong>, <strong>Skill Types</strong>, <strong>Employment Types</strong> and <strong>Job Positions</strong>.</td></tr></tbody></table><p>Inside <strong>Configurations</strong>, the left menu has three parts. <strong>Activity Plans</strong> stands alone. <strong>Employee</strong> holds Departure Reasons, Tags, Work Locations and Skill Types. <strong>Recruitment</strong> holds Employment Types and Job Positions.</p><h2 id="data-that-comes-ready-to-use" tabindex="-1">Data that comes ready to use <a class="header-anchor" href="#data-that-comes-ready-to-use" aria-label="Permalink to &quot;Data that comes ready to use&quot;">​</a></h2><p>A new installation includes sample records, so forms have choices from day one.</p><table tabindex="0"><thead><tr><th>Record</th><th>What you will find</th></tr></thead><tbody><tr><td>Departments</td><td>Administration, Long Term Projects, Management, Professional Services, R&amp;D USA, Research &amp; Development, Sales, Quality Check Department, Accounts</td></tr><tr><td>Tags</td><td>Sales, Trainer, Employee, Consultant, Management, HR, Engineering, Finance, Operations, Marketing, Support, Senior, Junior, Full-time</td></tr><tr><td>Skill types</td><td>Languages, Soft Skills, Programming Languages, IT, Marketing, Accounts, Quality Analyst</td></tr><tr><td>Work locations</td><td>Home, Building 1, Second Floor, Other</td></tr><tr><td>Departure reasons</td><td>Retired, Resigned, Fired</td></tr><tr><td>Activity plans</td><td>Offboarding, Onboarding, Verification, Review Candidate</td></tr><tr><td>Employment types</td><td>Employee, Statutory, Thesis, Apprenticeship, Student, Intern, Full-Time, Interim, Seasonal, Temporary, Permanent</td></tr></tbody></table><p>Job positions are also seeded, for example <strong>Software Engineer</strong>, <strong>Sales Manager</strong> and <strong>HR Manager</strong>.</p><h2 id="pages-in-this-module" tabindex="-1">Pages in this module <a class="header-anchor" href="#pages-in-this-module" aria-label="Permalink to &quot;Pages in this module&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./get-started/">Get started</a></td><td>A guided first run from department to employee list</td></tr><tr><td><a href="./employees/">Employees</a></td><td>Add, view, find and manage employee profiles</td></tr><tr><td><a href="./departments/departments.html">Departments</a></td><td>Build the company structure</td></tr><tr><td><a href="./setup/">Setup</a></td><td>Job positions, employment types, work locations, tags, departure reasons, skill types and activity plans</td></tr><tr><td><a href="./reporting/skills-report.html">Reporting</a></td><td>See skills across all employees</td></tr></tbody></table><h2 id="how-other-apps-use-employees" tabindex="-1">How other apps use employees <a class="header-anchor" href="#how-other-apps-use-employees" aria-label="Permalink to &quot;How other apps use employees&quot;">​</a></h2><ul><li><a href="./../time-off/">Time Off</a> uses the employee&#39;s Time Off approver and working hours.</li><li><a href="./../recruitment/">Recruitment</a> uses departments and job positions, and creates an employee when an applicant is hired.</li><li>Many apps use the employee&#39;s linked user to show who did what.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./get-started/first-steps.html">Get started: first steps</a></li><li><a href="./setup/">Setup overview</a></li><li><a href="./../../getting-started/search-filter-group.html">Search, filter and group</a></li></ul>`,22)]))}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
